#include <iostream>
#include <vector>
#include <cmath>

int main() {
    std::vector<int> l(2);
    for (int i = 0; i < 2; ++i) {
        std::cin >> l[i];
    }
    int p = l[0];
    int k = l[1];
    const long long MOD = 1000000007;

    auto mod_pow = [](long long base, long long exp, long long mod) -> long long {
        long long result = 1;
        base %= mod;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    };

    if (k == 0) {
        std::cout << mod_pow(p, p - 1, MOD) << std::endl;
    } else if (k == 1) {
        std::cout << mod_pow(p, p, MOD) << std::endl;
    } else {
        long long x = 1;
        int i;
        for (i = 1; i <= p; ++i) {
            x = (x * k) % p;
            if (x == 1) {
                break;
            }
        }
        std::cout << mod_pow(p, (p - 1) / i, MOD) << std::endl;
    }
    return 0;
}

